import{_ as i}from"./chunks/qr_ob1_debug.BFcqNe1b.js";import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o,o as t,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{"source_hash":"a64d69be78","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/troubleshoot/g6.md","filePath":"it/troubleshoot/g6.md"}'),s={name:"it/troubleshoot/g6.md"};function l(c,e,u,d,m,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="g6-one-troubleshooting" tabindex="-1">Risoluzione problemi G6, ONE <a class="header-anchor" href="#g6-one-troubleshooting" aria-label="Permalink to &quot;Risoluzione problemi G6, ONE {#g6-one-troubleshooting}&quot;">​</a></h1><p>Se non l&#39;hai già fatto, vedi prima <a href="./../install/g6.html">come configurare G6/ONE</a>. Questa pagina tratta i problemi comuni una volta connesso, o quelli che impediscono del tutto la connessione.</p><h2 id="no-connectivity-at-all" tabindex="-1">Nessuna connettività <a class="header-anchor" href="#no-connectivity-at-all" aria-label="Permalink to &quot;Nessuna connettività {#no-connectivity-at-all}&quot;">​</a></h2><ol><li>Parti dalle <a href="./../install/g6.html#prerequisites">impostazioni consigliate</a> e disattiva la modalità Engineering.</li><li>La comunicazione con il trasmettitore avviene una volta ogni 5 minuti: dopo aver cambiato un&#39;impostazione, attendi un ciclo di lettura completo prima di valutarne l&#39;effetto nella pagina di stato.</li><li>Assicurati che il trasmettitore sia attivato e che nessun altro telefono o dispositivo sia impostato per raccogliere dati da esso (se c&#39;è, scollegalo).</li><li>Controlla la <a href="./systemstatus.html">pagina Dex Status</a>. Se c&#39;è un comando bloccato nella coda, dovrebbe sparire entro il ciclo di lettura successivo; se non succede, <a href="#transmitter-queue-stuck">svuota la coda</a>.</li><li>Se la pagina di stato mostra &quot;Deep sleeping errors&quot; o &quot;Checking Auth errors&quot; con un orario &quot;Last Connected&quot; sempre inferiore a 5 minuti, tocca <strong>Dimentica questo dispositivo</strong> nella pagina Classic Status, torna alla pagina Dex Status e approva la nuova richiesta di associazione che segue (su Android 9 o precedenti non vedrai nessuna richiesta: l&#39;associazione avviene automaticamente). Se ancora non si connette, <a href="#triggering-a-pair-request-manually">avvia manualmente una richiesta di associazione</a>.</li><li>Se non ci sono disconnessioni e la pagina di stato mostra &quot;OK ** days&quot; come stato del sensore ma non ricevi letture, assicurati che la sessione di xDrip sia avviata: tocca Inizializza Sensore e inserisci il codice di calibrazione mostrato nella pagina di stato (non influisce su una sessione G6 già in corso).</li><li>Se ancora non funziona, disattiva la raccolta dati in xDrip, installa l&#39;app Dexcom e prova con quella. Se l&#39;app Dexcom si connette senza problemi, segnalalo: significa che il problema è dalla parte di xDrip, non del trasmettitore.</li></ol><p>Se hai connettività e letture ma ogni tanto si interrompono, vedi invece <a href="#intermittent-connectivity">Connettività intermittente</a>.</p><h2 id="intermittent-connectivity" tabindex="-1">Connettività intermittente <a class="header-anchor" href="#intermittent-connectivity" aria-label="Permalink to &quot;Connettività intermittente {#intermittent-connectivity}&quot;">​</a></h2><p>xDrip fa una scansione ogni 5 minuti per restare connesso e per il resto del tempo lavora in background per risparmiare batteria. Le versioni di Android più recenti (11+) e le funzioni di risparmio energetico dei produttori di telefoni possono interferire con questo, ed è per questo che i problemi di connessione iniziale sono frequenti con Android recenti.</p><ul><li>Assicurati di usare almeno l&#39;attuale release stabile di xDrip e parti dalle <a href="./../install/g6.html#prerequisites">impostazioni consigliate</a>.</li><li>Cerca le indicazioni specifiche per la marca del tuo telefono su <a href="https://dontkillmyapp.com/" target="_blank" rel="noreferrer">dontkillmyapp.com</a>.</li><li><strong>Pixel</strong>: disattivare l&#39;ottimizzazione della batteria richiede più di &quot;Consenti utilizzo in background&quot;: tocca la nota mostrata e scegli <strong>Senza restrizioni</strong>.</li><li><strong>Xiaomi</strong>: l&#39;ottimizzazione della batteria può riattivarsi da sola dopo ogni riavvio; potresti doverla disattivare di nuovo ogni volta.</li><li><strong>Unihertz</strong>: Impostazioni Android → Smart Assist → Power Save Manager, e aggiungi xDrip alla whitelist.</li><li><strong>Cubot</strong> (ad es. KingKong Mini): apri l&#39;app DuraSpeed preinstallata e togli xDrip dalle sue restrizioni di risparmio energetico.</li></ul><p>Se le disconnessioni continuano, prova queste opzioni una alla volta: attiva Abbinamento Speciale (può aiutare anche sui telefoni non Samsung), prova a disattivare Minimizza scansioni e sui dispositivi Samsung prova ad attivare Trust Auto-Connect nelle <a href="./../use/bluetooth.html">Impostazioni Bluetooth</a>.</p><h2 id="understanding-the-dex-status-page" tabindex="-1">Capire la pagina Dex Status <a class="header-anchor" href="#understanding-the-dex-status-page" aria-label="Permalink to &quot;Capire la pagina Dex Status {#understanding-the-dex-status-page}&quot;">​</a></h2><p>Aprila dal menu in alto a sinistra → <a href="./systemstatus.html">Stato del sistema</a>, poi scorri fino alla pagina &quot;Dex Status&quot;.</p><p>La connettività è OK quando: c&#39;è una riga &quot;Last Connected:&quot;, il suo valore resta sotto i 5 minuti mentre sei vicino al telefono, sale e torna a 0 a ogni ciclo di circa 5 minuti, e non ci sono messaggi come &quot;Hunting Transmitter&quot;, &quot;Scanning Error&quot;, &quot;Waiting Connect Errors&quot;, &quot;Checking Auth Errors&quot; o &quot;Deep Sleeping Errors&quot;. Uno qualsiasi di questi messaggi, o un valore &quot;Last Connected&quot; che non si comporta come descritto, indica una disconnessione: risolvila prima di inviare qualsiasi comando (avvio, arresto, calibrazione, hard reset).</p><p>xDrip riflette quello che il trasmettitore comunica una volta ogni 5 minuti (un sistema a campionamento e mantenimento), quindi dopo qualsiasi modifica o comando aspetta un ciclo completo (o due) prima di trarre conclusioni: non giudicare controllando la pagina di stato ogni pochi secondi.</p><div class="info custom-block"><p class="custom-block-title">Riprendere una sessione già avviata altrove</p><p>Se una sessione è già in corso (avviata da un altro telefono, da un&#39;altra app o da un dispositivo medico) non devi avviarne una nuova in xDrip: basta far funzionare la connettività come sopra e avere pazienza, possono volerci 10–15 minuti perché venga rilevata. Questo non vale per G7/ONE+ (che si avviano sempre automaticamente). Per G6/ONE, se il codice di calibrazione mostrato nella pagina Dex Status sembra sbagliato o manca, ignoralo: è il trasmettitore che ha bisogno del codice corretto, non xDrip, e conta di nuovo solo se avvii un sensore davvero nuovo.</p></div><p>L&#39;ID trasmettitore mostrato in questa pagina è unico per il tuo trasmettitore: fai attenzione a chi lo comunichi e oscuralo negli screenshot prima di pubblicarli per chiedere aiuto; nessuno ha bisogno di vederlo per aiutarti.</p><h2 id="sensor-wont-start-sensor-failed-messages" tabindex="-1">Il sensore non si avvia / messaggi &quot;sensor failed&quot; <a class="header-anchor" href="#sensor-wont-start-sensor-failed-messages" aria-label="Permalink to &quot;Il sensore non si avvia / messaggi &quot;sensor failed&quot; {#sensor-wont-start-sensor-failed-messages}&quot;">​</a></h2><p>La maggior parte di questi casi dipende dal fatto che il trasmettitore non è sicuro che si tratti davvero dell&#39;avvio di un nuovo sensore:</p><ul><li>Il trasmettitore deve restare fuori da qualsiasi sensore per almeno <strong>10 minuti</strong> prima di avviarne uno nuovo. Un errore comune è applicare il nuovo sensore mentre il vecchio è ancora attivo, fermare il vecchio e inserire subito il trasmettitore nel nuovo sensore: poiché non è mai rimasto fuori per 10 minuti, il trasmettitore lo considera un tentativo di riavvio e fa fallire il nuovo sensore con un errore.</li><li>Assicurati di avere una <a href="#understanding-the-dex-status-page">connettività corretta</a> prima di tentare l&#39;avvio: se non ce l&#39;hai, risolvi prima quel problema invece di ripetere avvio/arresto.</li><li>Se ricevi un messaggio &quot;sensor start failed&quot;, aspetta invece di riprovare più volte: i tentativi ripetuti senza risolvere il problema di fondo di connettività o di tempistica tendono a peggiorare la situazione.</li></ul><h2 id="transmitter-queue-stuck" tabindex="-1">Coda del trasmettitore bloccata <a class="header-anchor" href="#transmitter-queue-stuck" aria-label="Permalink to &quot;Coda del trasmettitore bloccata {#transmitter-queue-stuck}&quot;">​</a></h2><p>Il trasmettitore resta in ascolto solo per un breve momento ogni 5 minuti; per il resto del tempo è silenzioso per risparmiare batteria. Qualsiasi comando che invii (Inizializza Sensore, Stop Sensore, Calibra) resta in coda fino alla finestra successiva: lo vedrai elencato nella pagina Dex Status. Finché è elencato, il trasmettitore non l&#39;ha ancora ricevuto, quindi non inviare un altro comando sopra, e soprattutto non inviare comandi quando non hai una connettività corretta: potresti restare completamente bloccato.</p><p>Se un comando è in coda da più di 5 minuti e non riesci a stabilire la connettività, svuota la coda:</p><ol><li>Tocca il simbolo del contagocce (trattamento) nella schermata principale.</li><li>Tieni premuta l&#39;icona del microfono in basso a destra per ottenere un campo di testo invece dell&#39;input vocale.</li><li>Digita <code>clear transmitter queue</code> e conferma.</li></ol><p>Non svuotare la coda solo perché un comando vi resta normalmente dopo averlo inviato: è previsto, e svuotarla impedirebbe al comando di essere mai applicato.</p><h2 id="triggering-a-pair-request-manually" tabindex="-1">Avviare manualmente una richiesta di associazione <a class="header-anchor" href="#triggering-a-pair-request-manually" aria-label="Permalink to &quot;Avviare manualmente una richiesta di associazione {#triggering-a-pair-request-manually}&quot;">​</a></h2><ol><li>Impostazioni → Dexcom trasmettitore ID. Annota il valore attuale (scrivilo o fai uno screenshot).</li><li>Cambia l&#39;ultimo carattere con un altro qualsiasi e applica.</li><li>Rimetti il valore corretto e applica.</li><li>Vai alla <a href="./systemstatus.html">pagina Dex Status</a>: dovresti vedere &quot;Hunting Transmitter&quot; in rosso.</li><li>Entro 5 minuti dovresti ricevere una richiesta di associazione su Android 10+: approvala. Su Android 9 o precedenti l&#39;associazione avviene automaticamente senza alcuna richiesta visibile.</li><li>Se lo schermo è bloccato quando arriva la notifica della richiesta, sbloccalo, abbassa la tendina delle notifiche e approvala da lì.</li></ol><h2 id="how-strong-is-the-transmitter-signal" tabindex="-1">Quanto è forte il segnale del trasmettitore? <a class="header-anchor" href="#how-strong-is-the-transmitter-signal" aria-label="Permalink to &quot;Quanto è forte il segnale del trasmettitore? {#how-strong-is-the-transmitter-signal}&quot;">​</a></h2><p>Se il trasmettitore non sta davvero trasmettendo, nessuna configurazione di xDrip potrà risolverlo: uno scanner Bluetooth ti permette di verificarlo indipendentemente da xDrip.</p><ol><li>Installa un&#39;app scanner Bluetooth a scansione continua (ad es. &quot;BLE Scanner&quot;) su un telefono Android qualsiasi: non deve essere per forza quello su cui gira xDrip. Attenzione alle pubblicità sullo schermo in queste app.</li><li>Concedi i permessi richiesti, tieni il trasmettitore nella stessa stanza e lascialo scansionare.</li><li>Cerca un dispositivo chiamato <code>Dexcom**</code> (ultimi due caratteri del numero di serie del trasmettitore) per G6/ONE, oppure <code>DXCM**</code>/<code>DX02**</code>/<code>DX04**</code> (suffisso casuale) per G7/ONE+.</li><li>Annota il numero negativo della potenza del segnale accanto: potresti dover aspettare fino a 5 minuti perché compaia una voce in grassetto (attuale).</li><li>Se non compare mai, il trasmettitore non sta trasmettendo affatto. Se compare, comunica il nome del dispositivo e il numero a chi ti sta aiutando a risolvere il problema.</li></ol><h2 id="how-good-is-the-battery" tabindex="-1">Com&#39;è la batteria? <a class="header-anchor" href="#how-good-is-the-battery" aria-label="Permalink to &quot;Com&#39;è la batteria? {#how-good-is-the-battery}&quot;">​</a></h2><p>Le batterie dei trasmettitori si degradano anche in magazzino, quando non vengono usate: per questo la scatola riporta sia una data di fabbricazione sia una data di scadenza. Nella <a href="./systemstatus.html">pagina Dex Status</a> vedrai due tensioni, Voltage A e Voltage B. Variano da un trasmettitore all&#39;altro, ma quando una batteria si avvicina alla fine, Voltage B inizia un calo costante e continuo: vale la pena tenerla d&#39;occhio durante la vita del trasmettitore se le letture iniziano a sembrare poco affidabili verso la fine prevista della batteria.</p><h2 id="transmitter-warranty" tabindex="-1">Garanzia del trasmettitore <a class="header-anchor" href="#transmitter-warranty" aria-label="Permalink to &quot;Garanzia del trasmettitore {#transmitter-warranty}&quot;">​</a></h2><p>Un trasmettitore è in garanzia se valgono entrambe le condizioni: la data Use-By/Ship-By sulla scatola non era passata quando l&#39;hai avviato (o ricevuto), e hai iniziato a usarlo entro 5 mesi dal ricevimento. La copertura è di 90 giorni ininterrotti di funzionamento corretto. Per questo non conviene fare scorta di trasmettitori: la batteria invecchia comunque, e la garanzia può scadere prima che tu riesca a usare quello di riserva.</p><h2 id="hard-reset" tabindex="-1">Hard reset <a class="header-anchor" href="#hard-reset" aria-label="Permalink to &quot;Hard reset {#hard-reset}&quot;">​</a></h2><p>Un G6 può essere resettato (hard reset) tramite xDrip solo se il suo firmware è 1.6.5.25 o precedente: i firmware più recenti non possono essere resettati in questo modo. Un hard reset azzera il contatore dei giorni del trasmettitore nella pagina di stato; fallo solo quando non c&#39;è una sessione attiva (ad es. dopo aver fermato un sensore, prima di avviare il successivo).</p><ol><li>Verifica di avere una connettività corretta con il trasmettitore e disattiva l&#39;app Dexcom (xDrip e l&#39;app Dexcom non possono raccogliere entrambi i dati dallo stesso trasmettitore).</li><li>Nella schermata principale tocca il simbolo del contagocce (trattamento).</li><li>Tieni premuta l&#39;icona del microfono in basso a destra per ottenere un campo di testo.</li><li>Digita <code>Hard Reset Transmitter</code> e conferma: vedrai un messaggio che indica che il tentativo verrà eseguito. Non chiudere xDrip: il comando deve ancora raggiungere il trasmettitore.</li><li>Osserva la pagina di stato: l&#39;invio può richiedere fino a 5 minuti. Potresti vedere un avviso che indica che potrebbe non essere riuscito; in tal caso riavvia il telefono oppure forza l&#39;arresto di xDrip e riavvialo.</li><li>Rimuovi il trasmettitore dall&#39;elenco dei dispositivi Bluetooth connessi in precedenza di Android.</li></ol><p>Se intendi continuare a usare il trasmettitore, attivalo di nuovo come se fosse nuovo.</p><h2 id="restarting-a-sensor-beyond-its-normal-session" tabindex="-1">Riavviare un sensore oltre la sua sessione normale <a class="header-anchor" href="#restarting-a-sensor-beyond-its-normal-session" aria-label="Permalink to &quot;Riavviare un sensore oltre la sua sessione normale {#restarting-a-sensor-beyond-its-normal-session}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Leggi tutta questa sezione prima di provarci</p><p>Il riavvio non è approvato dal produttore e comporta rischi reali. Subito dopo il riscaldamento del riavvio le letture saranno nettamente (e prevedibilmente) troppo alte: se le correggi con insulina, o usi un loop chiuso senza prima aprirlo, puoi provocare un&#39;ipoglicemia.</p></div><p>Se il firmware del trasmettitore (mostrato nella pagina Dex Status) è 1.6.5.25 o precedente, puoi usare il riavvio preventivo di xDrip e saltare tutto questo: riavvia il sensore automaticamente al posto tuo. Altrimenti, se vuoi far funzionare lo <em>stesso</em> sensore oltre la sua normale sessione di 10 giorni, ecco come fare, usando il codice di calibrazione originale (i tentativi di riavvio senza codice registrano più segnalazioni di malfunzionamento):</p><ol><li>Assicurati prima che la connettività sia solida: il riavvio non risolve un problema di connettività di fondo, e comunque non devi riavviare prima del decimo giorno, solo se scegli di farlo.</li><li>Tocca Stop Sensore (menu in alto a sinistra), anche se è già fermo e Stop Sensore è l&#39;unica opzione mostrata. Aspetta che la coda si svuoti nella pagina di stato (~5 minuti) prima di continuare: vedrai poi &quot;Sensor: Stopped&quot;.</li><li><a href="#removing-a-transmitter-without-damaging-the-sensor">Rimuovi il trasmettitore senza danneggiare il sensore</a>.</li><li>Aspetta almeno 10 minuti con il trasmettitore fuori.</li><li>Reinserisci il trasmettitore e usa Inizializza Sensore, inserendo di nuovo il codice di calibrazione <em>originale</em>.</li></ol><p>Dopo le 2 ore di riscaldamento, aspettati letture nettamente alte: il trasmettitore crede ora di essere al giorno 1 di un sensore nuovo, mentre la reazione reale del tuo corpo al sensore è quella di un sensore vecchio di diversi giorni. Dovrai calibrare con attenzione: non correggere più del 20% alla volta, distanzia le calibrazioni di almeno 25 minuti (45 per una terza) e calibra solo quando la tendenza è piatta, altrimenti rischi un errore di calibrazione confusa. Durante questa fase vedrai &quot;Received backfill packet out of sequence&quot; nei log; è previsto e puoi ignorarlo. Come con qualsiasi sensore che invecchia, continua poi a controllare ogni tanto con un glucometro.</p><h2 id="changing-the-bluetooth-slot-advanced-not-recommended" tabindex="-1">Cambiare lo slot Bluetooth (avanzato, sconsigliato) <a class="header-anchor" href="#changing-the-bluetooth-slot-advanced-not-recommended" aria-label="Permalink to &quot;Cambiare lo slot Bluetooth (avanzato, sconsigliato) {#changing-the-bluetooth-slot-advanced-not-recommended}&quot;">​</a></h2><p>Un trasmettitore G6 ha due slot di comunicazione: è così che puoi usare un microinfusore t:slim <em>e</em> vedere le letture in xDrip, oppure usare insieme un ricevitore Dexcom e xDrip. xDrip usa per impostazione predefinita lo slot 2; un microinfusore t:slim e il ricevitore Dexcom usano entrambi lo slot 1.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Questa impostazione è ancora nascosta dietro la modalità Engineering perché i test hanno prodotto risultati inattesi, compresi trasmettitori disattivati in modo permanente. Al momento non è consigliata.</p></div><p>Se vuoi comunque cambiarla: attiva la <a href="./../use/misc.html#engineering-mode">modalità Engineering</a>, poi Impostazioni → Impostazioni di debug G5/G6 → &quot;Manual Slot Number&quot;, e impostalo a <code>1</code> per forzare lo slot non predefinito (disattivare la modalità Engineering riporta al valore predefinito). Due app collector che usano i due slot diversi non possono funzionare sullo stesso telefono.</p><h2 id="removing-a-transmitter-without-damaging-the-sensor" tabindex="-1">Rimuovere un trasmettitore senza danneggiare il sensore <a class="header-anchor" href="#removing-a-transmitter-without-damaging-the-sensor" aria-label="Permalink to &quot;Rimuovere un trasmettitore senza danneggiare il sensore {#removing-a-transmitter-without-damaging-the-sensor}&quot;">​</a></h2><p>Normalmente, quando stacchi un sensore lo apri, togli il trasmettitore e butti via il sensore. Ecco come rimuovere il trasmettitore lasciando il sensore intatto e ancora applicato sul corpo, ad esempio per spostarlo su un sensore nuovo.</p><p>Durante l&#39;operazione non toccare i contatti né del trasmettitore né del sensore.</p><p>Il sensore ha due linguette che si agganciano ai lati del trasmettitore, tenute in tensione dal materiale flessibile all&#39;interno dell&#39;alloggiamento del sensore. Per sganciarle ti serve qualcosa di sottile e resistente con cui spingere delicatamente ogni linguetta lontano dal trasmettitore: ritaglia una piccola striscia dall&#39;involucro di plastica di un sensore di riserva e arrotondane gli angoli con le forbici per ottenere un semplice attrezzo (tienilo lontano da bambini e animali: in mani piccole c&#39;è rischio di soffocamento).</p><p>Inserisci delicatamente l&#39;estremità più larga e arrotondata della striscia tra il sensore e il trasmettitore, proprio dove si trova una linguetta, finché non senti o non avverti lo scatto di sgancio. Il materiale compresso all&#39;interno spinge poi da solo il trasmettitore verso l&#39;esterno su quel lato: non serve fare altra leva, evita solo di premere sulla parte superiore del trasmettitore, che lo farebbe riagganciare. Ripeti dall&#39;altro lato e il trasmettitore si solleva.</p><h2 id="what-not-to-do" tabindex="-1">Cosa non fare <a class="header-anchor" href="#what-not-to-do" aria-label="Permalink to &quot;Cosa non fare {#what-not-to-do}&quot;">​</a></h2><ul><li>Non togliere un trasmettitore dalla scatola, né toccarne i contatti, prima di essere pronto a usarlo: il contatore dei giorni parte subito e non può essere messo in pausa.</li><li>Non buttare la pellicola adesiva di un sensore prima di aver annotato il codice di calibrazione stampato sopra.</li><li>Non pre-inserire un sensore (inserirlo molto prima di avviarlo in xDrip): interferisce con la calibrazione di fabbrica.</li><li>Non avviare un sensore se il trasmettitore non è rimasto prima fuori da qualsiasi sensore per almeno 10 minuti.</li><li>Non correggere più del 20% di una lettura in una singola calibrazione.</li><li>Non fermare un sensore solo perché pensi di poterlo riavviare facilmente: c&#39;è quasi sempre un&#39;opzione migliore che fermarlo.</li><li>Quando cambi telefono, ricordati di disattivare la raccolta dati su quello vecchio, altrimenti i due telefoni si contenderanno la connessione.</li><li>Non tentare un <a href="#restarting-a-sensor-beyond-its-normal-session">riavvio</a> senza capire e accettare i rischi: non è approvato dal produttore e le letture saranno sbagliate per un po&#39; di tempo.</li></ul><h2 id="ob1-debugging-logs" tabindex="-1">Log di debug OB1 <a class="header-anchor" href="#ob1-debugging-logs" aria-label="Permalink to &quot;Log di debug OB1 {#ob1-debugging-logs}&quot;">​</a></h2><p>Vale allo stesso modo per G6, ONE, G7 e ONE+: usano tutti lo stesso collector OB1, che per impostazione predefinita registra pochissimi dettagli nei log. Se uno sviluppatore ti chiede log dettagliati durante la risoluzione di un problema di connessione, attiva prima il logging OB1 completo.</p><p>Il modo più semplice è scansionare questo codice QR con Impostazioni, <a href="./../use/copysettings.html#auto-configure">Configurazione automatica</a> e approvare la richiesta di importazione. Imposta una sola preferenza, Tag aggiuntivi per la registrazione.</p><p>Codice QR - Fai clic sull&#39;immagine per ingrandirla</p><p><a href="../../troubleshoot/images/qr_ob1_debug.png"><img src="'+i+'" style="zoom:50%;"></a></p><p>Puoi anche inserire i tag a mano:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/lesscommon.html#extra-logging-settings">Impostazioni di log supplementari</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Tag aggiuntivi per la registrazione</p><p> Ob1G5CollectionService:v,Ob1G5StateMachine:v</p></div><p>Poi:</p><ul><li>Aspetta che il problema si verifichi davvero prima di caricare i log. Attivare il logging da solo non registra ancora nulla di utile.</li><li>Apri il <a href="./../use/3dotsmenu.html#events-log">Log eventi</a> dal menu a 3 puntini, tocca Upload Logs e aggiungi una nota che identifichi il dispositivo, così potrà essere riconosciuto quando lo segnali.</li><li>Disattivalo dopo: svuota il campo Tag aggiuntivi per la registrazione e conferma. Altrimenti continua a generare un grande volume di log in più.</li></ul>',62)])])}const f=o(s,[["render",l]]);export{b as __pageData,f as default};
